  const ScrobbleSecret({required this.key, required this.secret, required this.token, required this.server});

  @override
  int get hashCode => key.hashCode ^ secret.hashCode ^ token.hashCode ^ server.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ScrobbleSecret &&
          runtimeType == other.runtimeType &&
          key == other.key &&
          secret == other.secret &&
          token == other.token &&
          server == other.server;
}

/// Where a sign-in stands: asking the listener to type `code` on the page at `url`, or, with no
/// code, to approve on that page, which hands the answer back to a local address; or, last,
/// signed in as `name`.
class SignInEvent {
  final String? code;
  final String url;
  final String? name;

  const SignInEvent({this.code, required this.url, this.name});

  @override
  int get hashCode => code.hashCode ^ url.hashCode ^ name.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SignInEvent &&
          runtimeType == other.runtimeType &&
          code == other.code &&
          url == other.url &&
          name == other.name;
}

class StorageUsage {
