/// A track as screens draw it, and as they hand it back to be queued. `source` is the provider
/// slug, or `local` for a file.
class TrackItem {
  final String source;
  final String id;
  final String title;
  final String artists;
  final String album;
  final String? cover;

  /// The same cover asked for at full-screen size.
  final String? coverLarge;
  final BigInt durationMs;
  final bool playable;

  /// Where "Go to album" leads, when the provider names the album.
  final String? albumId;

  /// Where "Go to artist" leads: every credited artist the provider can open.
  final List<ArtistLink> artistLinks;

  const TrackItem({
    required this.source,
    required this.id,
    required this.title,
    required this.artists,
    required this.album,
    this.cover,
    this.coverLarge,
    required this.durationMs,
    required this.playable,
    this.albumId,
    required this.artistLinks,
  });

  @override
  int get hashCode =>
      source.hashCode ^
      id.hashCode ^
      title.hashCode ^
      artists.hashCode ^
      album.hashCode ^
      cover.hashCode ^
      coverLarge.hashCode ^
      durationMs.hashCode ^
      playable.hashCode ^
      albumId.hashCode ^
      artistLinks.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TrackItem &&
          runtimeType == other.runtimeType &&
          source == other.source &&
          id == other.id &&
          title == other.title &&
          artists == other.artists &&
          album == other.album &&
          cover == other.cover &&
          coverLarge == other.coverLarge &&
          durationMs == other.durationMs &&
          playable == other.playable &&
          albumId == other.albumId &&
          artistLinks == other.artistLinks;
}

